SELECT jsonb_build_object(
'bindings',jsonb_build_object(
'prepared_sources',(SELECT to_jsonb(x) FROM mission_factory_owner.c395_prepared_sources x WHERE session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'),
'human_bindings',(SELECT to_jsonb(x) FROM mission_factory_owner.c384_human_bindings x WHERE session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'),
'run_bindings',(SELECT to_jsonb(x) FROM mission_generic_owner.run_bindings x WHERE master_session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268')),
'events',(SELECT jsonb_agg(jsonb_build_object('id',own_event_capture.id,'sha',mission_factory_owner.sha(to_jsonb(own_event_capture))) ORDER BY own_event_capture.id) FROM public.mission_run_events own_event_capture WHERE master_session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'),
'outbox',(SELECT jsonb_agg(jsonb_build_object('sha',mission_factory_owner.sha(to_jsonb(o))) ORDER BY mission_factory_owner.sha(to_jsonb(o))) FROM public.mission_run_outbox o WHERE master_session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'),
'roles',(SELECT jsonb_agg(jsonb_build_object('id',msg.id,'character_id',msg.character_id,'sha',encode(extensions.digest(convert_to(msg.body,'UTF8'),'sha256'),'hex'),'length',length(msg.body)) ORDER BY msg.id) FROM public.messages msg WHERE msg.id IN(SELECT id FROM public.messages WHERE id::text LIKE '94c8bb51%' OR id::text LIKE '598cbc02%')),
'native',(SELECT jsonb_agg(jsonb_build_object('id',d.id,'cv',d.control_version,'sha',d.document_sha256,'row_sha256',mission_factory_owner.sha(to_jsonb(d))) ORDER BY d.id) FROM mission_factory_owner.drafts d WHERE d.id IN('b2aa11b4-5f8b-43c9-bbb8-1db7a85739f9','e6d1b561-cc76-4fb9-8e4e-b73ffc86b6be'))
,
'human_encounters',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM mission_creation_owner.human_encounters cap WHERE master_session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'),
'combat',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM public.combat_v2_sessions cap WHERE id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70'),
'rounds',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM public.combat_v2_rounds cap WHERE session_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70'),
'actors',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM public.combat_v2_actors cap WHERE session_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70'),
'arena',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM combat_spatial.arena_instances cap WHERE encounter_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70'),
'npc_offers',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM public.master_v2_nb_actor_offers_v1 cap WHERE master_session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'),
'regia_admissions',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM mission_generic_owner.regia_human_admissions_v1 cap WHERE master_session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'),
'regia_windows',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM mission_generic_owner.regia_human_windows_v1 cap WHERE encounter_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70'),
'unified_windows',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM mission_generic_owner.unified_round_windows cap WHERE master_session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'),
'declarations',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM public.combat_v2_declarations cap WHERE round_id IN(SELECT id FROM public.combat_v2_rounds WHERE session_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70')),
'reports',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM public.combat_v2_round_reports cap WHERE round_id IN(SELECT id FROM public.combat_v2_rounds WHERE session_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70')),
'spatial_actors',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM combat_spatial.actor_states cap WHERE instance_id='5338ee1c-fe73-904e-f13a-dbee83f43f17'),
'spatial_objects',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM combat_spatial.object_states cap WHERE instance_id='5338ee1c-fe73-904e-f13a-dbee83f43f17'),
'spatial_events',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM combat_spatial.spatial_events cap WHERE instance_id='5338ee1c-fe73-904e-f13a-dbee83f43f17'),
'actor_claims',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM combat_spatial.binding_actor_claims cap WHERE encounter_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70'),
'viewer_claims',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM combat_spatial.binding_viewer_claims cap WHERE encounter_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70'),
'scene_claims',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM combat_panel_private.master_scene_claims cap WHERE encounter_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70'),
'attack_targets',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM public.combat_v2_attack_targets cap WHERE round_id IN(SELECT id FROM public.combat_v2_rounds WHERE session_id='9f5ad733-ea91-434f-8ffd-1a3c818e1e70')),
'unified_batches',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM mission_generic_owner.unified_batches cap WHERE id IN(SELECT batch_id FROM mission_generic_owner.unified_round_windows WHERE master_session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268')),
'human_directions',(SELECT jsonb_build_object('count',count(*),'sha',mission_factory_owner.sha(coalesce(jsonb_agg(to_jsonb(cap) ORDER BY to_jsonb(cap)::text),'[]'::jsonb))) FROM mission_creation_owner.human_directions cap WHERE master_session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268')) AS evidence;
